// ===========================================================================
// nuliga-sync — n8n Code node
//
// Setup:
//   1. Docker env (einmalig): NODE_FUNCTION_ALLOW_EXTERNAL=cheerio,js-yaml
//   2. Im vorgelagerten "Config"-Set-Node alle 5 Werte eintragen
//      (githubToken, githubOwner, githubRepo, pushoverToken, pushoverUser)
//   3. Unten den Platzhalter zwischen den --- PASTE BUNDLE --- Markern
//      durch den Inhalt von tools/nuliga-sync/dist/n8n-bundle.js ersetzen.
//
// Output:
//   { changed: false }                                → If-Node nimmt False-Pfad
//   { changed: true, prUrl, prTitle, prBody, errors } → If-Node nimmt True-Pfad → Pushover
// ===========================================================================

const cheerio = require('cheerio');
const yaml = require('js-yaml');

// --- PASTE BUNDLE BELOW ---
// ... entire content of tools/nuliga-sync/dist/n8n-bundle.js goes here ...
// --- PASTE BUNDLE ABOVE ---

const config = $('Config').first().json;
const GITHUB_TOKEN = config.githubToken;
const OWNER = config.githubOwner;
const REPO = config.githubRepo;
const API = `https://api.github.com/repos/${OWNER}/${REPO}`;

// GitHub API helper using n8n's built-in httpRequest (runner-sandbox-safe)
const gh = async (path, opts = {}) => {
  const reqOpts = {
    method: opts.method ?? 'GET',
    url: `${API}${path}`,
    headers: {
      'Authorization': `Bearer ${GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github+json',
      'User-Agent': 'nuliga-sync',
    },
    json: true,
  };
  if (opts.body !== undefined) {
    reqOpts.body = typeof opts.body === 'string' ? JSON.parse(opts.body) : opts.body;
  }
  try {
    return await this.helpers.httpRequest(reqOpts);
  } catch (err) {
    throw new Error(`GitHub API ${path}: ${err.message}`);
  }
};

// Fetch-shim for liga.nu HTML — returns fetch-API-compatible response object
const fetchShim = async (url) => {
  try {
    const text = await this.helpers.httpRequest({
      method: 'GET',
      url,
      json: false,
    });
    return {
      ok: true,
      status: 200,
      text: async () => typeof text === 'string' ? text : String(text),
    };
  } catch (err) {
    return {
      ok: false,
      status: err.statusCode ?? 500,
      text: async () => err.message,
    };
  }
};

const readRepoFile = async (path) => {
  const data = await gh(`/contents/${encodeURI(path)}?ref=main`);
  return Buffer.from(data.content, 'base64').toString('utf8');
};

const findOpenSyncPR = async () => {
  const pulls = await gh(`/pulls?state=open&per_page=50`);
  return pulls.find(p => p.head.ref.startsWith('nuliga-sync/'));
};

const commitAndOpenPR = async ({ branch, commitMessage, prTitle, prBody, fileChanges }) => {
  const mainRef = await gh('/git/ref/heads/main');
  const baseSha = mainRef.object.sha;

  await gh('/git/refs', {
    method: 'POST',
    body: { ref: `refs/heads/${branch}`, sha: baseSha },
  });

  const baseCommit = await gh(`/git/commits/${baseSha}`);
  const baseTree = baseCommit.tree.sha;

  const treeEntries = fileChanges.map(f => ({
    path: f.path,
    mode: '100644',
    type: 'blob',
    content: f.content,
  }));

  const tree = await gh('/git/trees', {
    method: 'POST',
    body: { base_tree: baseTree, tree: treeEntries },
  });

  const commit = await gh('/git/commits', {
    method: 'POST',
    body: { message: commitMessage, tree: tree.sha, parents: [baseSha] },
  });

  await gh(`/git/refs/heads/${branch}`, {
    method: 'PATCH',
    body: { sha: commit.sha },
  });

  const pr = await gh('/pulls', {
    method: 'POST',
    body: {
      title: prTitle,
      body: prBody,
      head: branch,
      base: 'main',
      draft: true,
    },
  });

  try {
    await gh(`/issues/${pr.number}/labels`, {
      method: 'POST',
      body: { labels: ['automated', 'nuliga-sync'] },
    });
  } catch (e) {
    // labels optional
  }

  return pr;
};

const commentOnPR = async (prNumber, body) => {
  await gh(`/issues/${prNumber}/comments`, {
    method: 'POST',
    body: { body },
  });
};

const result = await runSync({
  fetchImpl: fetchShim,
  readRepoFile,
  today: new Date(),
});

if (!result.changed) {
  return [{ json: { changed: false, errors: result.errors, newResults: [] } }];
}

const existingPR = await findOpenSyncPR();
if (existingPR) {
  await commentOnPR(existingPR.number, `Zusätzliche Änderungen seit PR-Erstellung:\n\n${result.prBody}`);
  return [{
    json: {
      changed: true,
      action: 'comment',
      prUrl: existingPR.html_url,
      prTitle: existingPR.title,
      prBody: result.prBody,
      errors: result.errors,
      newResults: result.newResults ?? [],
    },
  }];
}

const pr = await commitAndOpenPR(result);
return [{
  json: {
    changed: true,
    action: 'created',
    prUrl: pr.html_url,
    prNumber: pr.number,
    prTitle: result.prTitle,
    prBody: result.prBody,
    errors: result.errors,
    newResults: result.newResults ?? [],
  },
}];
